import{_ as i,l,o as e,c as p,v as t,p as n,x as o,d as s,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"晶圆厂资本开支","description":"","frontmatter":{"title":"晶圆厂资本开支","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/fab-capex.md","filePath":"litho/fab-capex.md","lastUpdated":1789023840000}'),h={name:"litho/fab-capex.md"};function E(A,a,_,m,x,f){const r=l("Mermaid");return e(),p("div",null,[a[1]||(a[1]=t('<h1 id="晶圆厂资本开支" tabindex="-1">晶圆厂资本开支 <a class="header-anchor" href="#晶圆厂资本开支" aria-label="Permalink to &quot;晶圆厂资本开支&quot;">​</a></h1><div class="epigraph"><p>先进逻辑厂的资本开支里，光刻设备占很大一截，但不是全部：洁净室、电源、真空、刻蚀与计量一起付款。</p><footer>—— 对照领先晶圆厂 capex 结构的公开产业讨论；不编造某厂亿美元数</footer></div><p><a href="/litho/capacity-planning-bottleneck">上一课</a>数了瓶颈台数。缺口是整张支票。本课钉晶圆厂资本开支。摩尔叙事如何从光刻视角阅读，留给[下一课](/litho/moore-litho-view）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Capex = 厂房 + 设施（电、水、超纯、真空、排气）+ 设备（光刻、刻蚀、薄膜、CMP、检测、植入）。EUV 还要源、氢、锡、特殊真空。高 NA 再加更大的工具与设施接口。光刻占比高，但把 capex 全写成「ASML 发票」会漏掉设施与配套。周期：建设年与设备安装年的现金流不同，规划课的台数是峰值工具，不是第一年就全部到齐。</p><p>缺口是<strong>整厂支票</strong>，不是单机折旧公式。不引用未核实的「某厂 200 亿美元」当定律。</p><h3 id="光刻占比随节点变" tabindex="-1">光刻占比随节点变 <a class="header-anchor" href="#光刻占比随节点变" aria-label="Permalink to &quot;光刻占比随节点变&quot;">​</a></h3><p>迁 EUV 提高光刻份额；3D NAND 把份额推向刻蚀（后课）。逻辑与存储的 capex 结构不同，不能用一个百分比。</p><p><span class="marginnote">出口管制与交货期会把 capex 计划变成「有钱买不到」——供应链课将展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>情景：目标 wpm × 瓶颈台数 × 单价 + 设施因子。灵敏度：EUV 层数、高 NA 插入年。与折旧：capex 是现金；折旧是后续晶圆成本。两者都要看，对象不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>固定成本极高导致必须规模：小厂摊不进先进光刻。这是代工集中的资本原因之一，不完全是技术秘密。</p>',13)),(e(),n(c,null,{default:o(()=>[d(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOOL%5B%22%E5%85%89%E5%88%BB%20%2B%20%E9%85%8D%E5%A5%97%E8%AE%BE%E5%A4%87%22%5D%20--%3E%20CAP%5B%22Fab%20capex%22%5D%0A%20%20FAC%5B%22%E5%8E%82%E6%88%BF%E8%AE%BE%E6%96%BD%22%5D%20--%3E%20CAP%0A%20%20CAP%20--%3E%20SCALE%5B%22%E8%A7%84%E6%A8%A1%E9%97%A8%E6%A7%9B%22%5D%0A%20%20SCALE%20--%3E%20CONC%5B%22%E4%BA%A7%E8%83%BD%E9%9B%86%E4%B8%AD%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不给投资建议。不把 capex 当运营成本。各国补贴改变谁付支票，不改变物理台数。</p><p>后课默认：先进光刻有规模门槛；下一课用摩尔定律的光刻读法看为什么支票越来越大仍在开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Fab capex 含水电厂房与全套设备，光刻是大头但非全部。</li><li>逻辑与存储结构不同；EUV/高 NA 抬光刻份额。</li><li>规模门槛推动产能集中。</li><li>出处：晶圆厂 capex 结构的公开产业讨论。</li></ul>',5))])}const B=i(h,[["render",E]]);export{b as __pageData,B as default};
